		"#define FALSE 0",
		"",
		"// ------ string -------",
		"",
		"bool eqstr(char* s, char* t)",
		"{",
		"    return strcmp(s, t) == 0;",
		"} ",
		"",
		"// ----- Strings ----",
		"",
		"char* copystr(const char* str)",
		"{",
		"    int len = strlen(str);",
