		"        goto s0;",
		"    }",
		"    if (it-&gt;base.ch == '\"')",
		"    {",
		"        it-&gt;_state = 2; return; s2:",
		"        it-&gt;base.ch = it-&gt;_a;",
		"        it-&gt;base.line = it-&gt;_source_it-&gt;line;",
		"        it-&gt;base.column = it-&gt;_source_it-&gt;column;",
		"        ",
		"        while (it-&gt;base.ch != '\\0' &amp;&amp; it-&gt;base.ch != '\"')",
		"        {",
		"            if (it-&gt;base.ch == '\\\\')",
		"            {",
		"                it-&gt;_state = 3; return; s3:",
