		"}",
		"",
		"int my_left = 0;",
		"char *my_mem = 0;",
		"#define ALLOC_SIZE 100000",
		"",
		"void* my_malloc(int size)",
		"{",
		"    if (my_left &lt; size)",
		"    {",
