		"        return ch - '0';",
		"    if ('A' &lt;= ch &amp;&amp; ch &lt;= 'F')",
		"        return ch - ('A' - 10);",
		"    return -1;",
		"}",
		"",
		"typedef struct label_s *label_p;",
		"struct label_s",
		"{",
		"    char *name;",
		"    int ip;",
		"};",
		"",
		"unsigned int hash(const char *name, int len)",
		"{",
