		"}",
		"",
		"ssize_t fgetc(FILE *stream)",
		"{",
		"    if (stream-&gt;mode == 'r')",
		"    {",
		"        if (stream-&gt;pos &gt;= stream-&gt;size)",
		"        {",
		"            stream-&gt;at_eof = 1;",
		"            return -1;",
		"        }",
		"        return stream-&gt;buffer[stream-&gt;pos++];",
		"    }",
		"    if (stream-&gt;at_eof)",
		"        return -1;",
		"    unsigned char ch;",
		"    ssize_t ret = SYSCALL_READ(stream-&gt;fh, &amp;ch, 1);",
		"    if (ret &lt;= 0)",
		"    {",
		"        stream-&gt;at_eof = 1;",
		"        return -1;",
		"    }",
		"    return ch;",
		"}",
