		"",
		"size_t sscanf(const char *str, const char *format, ...)",
		"{",
		"    va_list ap;",
		"    va_start(ap, format);",
		"",
		"    size_t args_parsed = 0;",
		"",
		"    while (*format != '\\0')",
		"        if (*str == '\\0')",
		"            break;",
		"        else if (*format == '%')",
		"        {",
		"            format++;",
		"            if (*format == 'd')",
		"            {",
		"                format++;",
		"                size_t v = 0;",
		"                while ('0' &lt;= *str &amp;&amp; *str &lt;= '9')",
		"                {",
		"                    v = 10 * v + *str - '0';",
		"                    str++;",
		"                }",
		"                **((ssize_t**)ap) = v;",
		"                ap++;",
		"                args_parsed++;",
		"            }",
		"            else",
		"            {",
		"                fprintf(stderr, \"sscanf: format %%%c not supported\\n\", *format);",
		"                exit(1);",
		"            }",
		"        }",
		"        else",
		"        {",
		"            if (*format != *str)",
		"                break;",
		"            format++;",
		"            str++;",
		"        }",
		"    return args_parsed;",
		"}",
