		"    ",
		"    for (size_t i = 0; i &lt; len - 1; i++)",
		"    {",
		"        if (feof(f))",
		"        {",
		"            str[i] = '\\0';",
		"            break;",
		"        }",
		"        str[i] = ch;",
		"        if (ch == '\\n')",
		"        {",
		"            str[i+1] = '\\0';",
		"            break;",
		"        }",
		"        ch = fgetc(f);",
		"    }",
		"    return str;",
		"}",
