		"                             ### if you wish to use this header, you need to add :ELF_end to the end of your",
		"                             ### M1 or hex2 files.",
		"                             ",
		"                             ## ELF Header",
		"                             ",
		"                             ",
		"7F 45 4C 46                  # e_ident[EI_MAG0-3] ELF's magic number",
		"                             ",
		"02                           # e_ident[EI_CLASS] Indicating 64 bit",
		"01                           # e_ident[EI_DATA] Indicating little endianness",
		"01                           # e_ident[EI_VERSION] Indicating original elf",
		"                             ",
		"03                           # e_ident[EI_OSABI] Set at 3 because FreeBSD is strict",
		"00                           # e_ident[EI_ABIVERSION] See above",
		"                             ",
		"00 00 00 00 00 00 00         # e_ident[EI_PAD]",
		"                             ",
		"02 00                        # e_type Indicating Executable",
		"3E 00                        # e_machine Indicating AMD64",
		"01 00 00 00                  # e_version Indicating original elf",
		"                             ",
		"78800408 00 00 00 00         # e_entry Address of the entry point",
		"40000000 00 00 00 00         # e_phoff Address of program header table",
		"D4050000 00 00 00 00         # e_shoff Address of section header table",
		"                             ",
		"00 00 00 00                  # e_flags",
		"                             ",
		"40 00                        # e_ehsize Indicating our 64 Byte header",
		"                             ",
		"38 00                        # e_phentsize size of a program header table",
		"01 00                        # e_phnum number of entries in program table",
		"                             ",
		"40 00                        # e_shentsize size of a section header table",
		"05 00                        # e_shnum number of entries in section table",
		"                             ",
		"02 00                        # e_shstrndx index of the section names",
		"                             ",
		"                             ",
		"                             ",
		"                             ",
		"01 00 00 00                  # ph_type: PT-LOAD = 1",
		"07 00 00 00                  # ph_flags: PF-X|PF-W|PF-R = 7",
		"00 00 00 00 00 00 00 00      # ph_offset",
		"00800408 00 00 00 00         # ph_vaddr",
		"00800408 00 00 00 00         # ph_physaddr",
		"0C0B0000 00 00 00 00         # ph_filesz",
		"0C0B0000 00 00 00 00         # ph_memsz",
		"01 00 00 00 00 00 00 00      # ph_align",
		"                             ",
		"                             ",
		"                             #",
		"                             #:ELF_text",
		"                             #",
		"                             #:_start",
		"B8 0C000000                  #    mov_rax, %12                                # the Syscall # for SYS_BRK",
		"48C7C3 00000000              #    mov_rbx, %0                                 # Get current brk",
		"0F05                         #    syscall                                     # Let the kernel do the work",
		"488905 16050000              #    mov_[rip+DWORD],rax %SYS_MALLOC             # Set our malloc pointer",
		"                             #",
		"                             #    # allocate memory for the second stack",
		"B8 A0860100                  #    mov_rax, %100000",
		"50                           #    push_rax                                    # (sys_malloc assums address)",
