		"                    code = code - bound;",
		"                }",
		"            }",
		"            else",
		"            {",
		"                range = range - bound;",
		"                code = code - bound;",
		"                p = probs;",
		"                prob = p + 4 * (IsRepG1 + state);",
		"                ttt = prob[0];",
		"",
		"                if(range &lt; kTopValue)",
		"                {",
		"                    if(buf &gt;= bufLimit)",
		"                    {",
		"                        return DUMMY_ERROR;",
