		"                    code = code - bound;",
		"                    p = probs;",
		"                    prob = p + 4 * (IsRepG2 + state);",
		"                    ttt = prob[0];",
		"",
		"                    if(range &lt; kTopValue)",
		"                    {",
		"                        if(buf &gt;= bufLimit)",
		"                        {",
		"                            return DUMMY_ERROR;",
		"                        }",
		"",
		"                        range = range &lt;&lt; 8;",
		"                        code = (code &lt;&lt; 8) | (0xFF &amp; buf[0]);",
		"                        buf = buf + 1;",
		"                    }",
		"",
		"                    bound = (range &gt;&gt; kNumBitModelTotalBits) * ttt;",
		"",
		"                    if(code &lt; bound)",
