		"            /* Usually not present, just ignore it. */",
		"            if((bhf &amp; 64) != 0) IgnoreVarint();",
		"            /* Uncompressed size present. */",
		"            /* Usually not present, just ignore it. */",
		"            if((bhf &amp; 128) != 0) IgnoreVarint();",
