		"    k[42] = 0xc24b8b70;",
		"    k[43] = 0xc76c51a3;",
		"    k[44] = 0xd192e819;",
		"    k[45] = 0xd6990624;",
		"    k[46] = 0xf40e3585;",
		"    k[47] = 0x106aa070;",
		"    k[48] = 0x19a4c116;",
		"    k[49] = 0x1e376c08;",
		"    k[50] = 0x2748774c;",
		"    k[51] = 0x34b0bcb5;",
		"    k[52] = 0x391c0cb3;",
		"    k[53] = 0x4ed8aa4a;",
